const h=(value='')=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const channels=['C','M','Y','K','W'],channelLabels={C:'Ciano',M:'Magenta',Y:'Amarelo',K:'Preto',W:'Branco'},baseUnit={film:'m',powder:'g',ink:'ml'};
const number=value=>String(value??'').trim()===''?null:Number(String(value).replace(',','.'));
const fmt=(value,digits=2)=>Number.isFinite(Number(value))&&value!==null&&value!==undefined?Number(value).toLocaleString('pt-BR',{maximumFractionDigits:digits}):'—';
