    modal.querySelector('[data-cost-close]').onclick=()=>close();modal.onkeydown=event=>{if(event.key==='Escape'){event.preventDefault();close()}else if(event.key==='Tab'){const nodes=[...modal.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),summary,a[href]')].filter(node=>node.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}};document.body.style.overflow='hidden';document.body.appendChild(modal);modal.querySelector('[data-cost-close]').focus();return {modal,body:modal.querySelector('[data-cost-content]'),close,cleanups,isClosed:()=>closed};
